"""
Research sub page: Digital Twins (research-dt.html) — part 3 of the article series after MDE (part 1) and AI4SE (part 2).
What a digital twin is (the definition of RWTH Aachen's Software Engineering group and the Internet of Production), how
a twin works, and how twins are built with models. Imported by build.py; figures and demos in dt_figs.py, their
behaviour in assets/dt.js, article styles in assets/dt.css.

Structure (concept first, case study after): 01 explains the concepts on an everyday example, a car (ladder, anatomy,
shadows as database views, type vs instance); 02 shows how a twin works on the case study of the RWTH group's papers,
an injection-moulding machine (the hero); 03 builds twins with models, with wind turbines as a second case study.
Citations: at most about one per paragraph; paper detail goes into "For the curious" boxes.
"""
from ai4se import T, cite
from dt_figs import (REFS, r, fig_lifespans, fig_lifecycle, fig_refarch, fig_mde4dt, fig_wind, fig_sos,
                     demo_ladder, demo_anatomy, demo_shadows, demo_loop, demo_roles)
from mde import tries, gpt, curious
import article_common
import article_art

NL = "\n"
FILE = "research-dt.html"
OWN = ["DHM+22", "MNN+22", "FHM+23", "Net24"]

DT_DEF = ("A digital twin of an original system is a software that consists of", ["a set of models of the system and", "a set of digital shadows, both of which are purposefully updated on a regular basis, and",
          "provides a set of services to use both purposefully with respect to the original system."],
          "The digital twin interacts with the original system by", ["providing useful information about the system’s context and", "sending it control commands."])
DT_DEF_DE = ("Ein digitaler Zwilling eines Originalsystems ist eine Software, die besteht aus", ["einer Menge von Modellen des Systems und", "einer Menge digitaler Schatten, die beide zweckgerichtet und regelmäßig aktualisiert werden, und",
             "eine Menge von Services bereitstellt, um beide zweckgerichtet in Bezug auf das Originalsystem zu nutzen."],
             "Der digitale Zwilling interagiert mit dem Originalsystem, indem er", ["nützliche Informationen über den Kontext des Systems liefert und", "ihm Steuerbefehle sendet."])


def def_box(term, quote_parts, source, lang, translation=None):
    """A definition set apart, as quoted (with bullets as in the source); German pages add an own translation."""
    def render(parts):
        a, items, b, items2 = parts
        out = f"<p>{a}</p>" + (("<ul>" + "".join(f"<li>{i}</li>" for i in items) + "</ul>") if items else "")
        if b:
            out += f"<p>{b}</p><ul>" + "".join(f"<li>{i}</li>" for i in items2) + "</ul>"
        return out
    tr = f'<div class="defn-tr"><span class="mono">{T("own translation", "eigene Übersetzung")[lang]}</span>{render(translation)}</div>' if translation and lang == "de" else ""
    return f'<div class="defn defn-long"><span class="mono">{term}</span>{render(quote_parts)}<p class="defn-src mono">{source}</p>{tr}</div>'


def body(lang, A):
    L = lambda x: x[lang]
    S = []
    S.append(("intro", 0, None, L(T(
        f"""<p>Your electric car’s app shows its charge level and range, live, wherever you are. Is that a digital twin? Many would say yes. By the end of the first chapter you will be able to say why most researchers would not — and what is missing.</p>
<p>“Digital twin” has become one of the most used and least agreed-on words in engineering. This article uses the definition of the Software Engineering group at RWTH Aachen and the Internet of Production, a large research cluster at RWTH Aachen on digital production {r('essay')}. It builds on <a href="research-mde.html">part 1</a> of this series: a twin is <i>software</i>, made of <a href="research-mde.html#model">models</a>, and it can be engineered with <a href="research-mde.html#generator">generators</a>. Chapter 01 explains the concepts on a car. Chapter 02 shows how a twin works on the case study of the RWTH group’s papers, the injection-moulding machine in the figure above. Chapter 03 builds twins with models, with wind turbines as a second case study.</p>""",
        f"""<p>Die App Ihres Elektroautos zeigt Ladestand und Reichweite, live, wo immer Sie sind. Ist das ein digitaler Zwilling? Viele würden Ja sagen. Am Ende des ersten Kapitels können Sie begründen, warum die meisten Forschenden Nein sagen würden — und was fehlt.</p>
<p>„Digitaler Zwilling“ ist eines der meistbenutzten und am wenigsten geklärten Wörter der Ingenieurwelt geworden. Dieser Artikel nutzt die Definition der Software-Engineering-Gruppe der RWTH Aachen und des Internet of Production, eines großen Forschungsclusters der RWTH Aachen zur digitalen Produktion {r('essay')}. Er baut auf <a href="research-mde.html">Teil 1</a> dieser Reihe auf: Ein Zwilling ist <i>Software</i>, er besteht aus <a href="research-mde.html#model">Modellen</a>, und er lässt sich mit <a href="research-mde.html#generator">Generatoren</a> bauen. Kapitel 01 erklärt die Begriffe an einem Auto. Kapitel 02 zeigt, wie ein Zwilling arbeitet, an der Fallstudie aus den Arbeiten der RWTH-Gruppe: der Spritzgießmaschine in der Abbildung oben. Kapitel 03 baut Zwillinge mit Modellen, mit Windkraftanlagen als zweiter Fallstudie.</p>"""))))

    # ---------------- 01 What a digital twin is (everyday example: a car) ----------------
    S.append(("twin", 2, T("What a digital twin is", "Was ein digitaler Zwilling ist"), L(T(
        "<p>The example for this chapter is something you know: a car. First the why, then three words that are often confused — model, shadow, twin — the definition, and the difference between the twin of a car model and the twin of your car.</p>",
        "<p>Das Beispiel dieses Kapitels kennen Sie: ein Auto. Erst das Warum, dann drei oft verwechselte Wörter — Modell, Schatten, Zwilling —, die Definition und der Unterschied zwischen dem Zwilling eines Automodells und dem Zwilling Ihres Autos.</p>"))))
    S.append(("why", 3, T("Systems that outlive their software", "Systeme, die ihre Software überleben"),
        L(T(f"""<p>Production machines run for ten to fifteen years, bridges for fifty, buildings for up to a hundred. Over that time they are watched, maintained, adjusted and extended — and the knowledge needed for this is scattered across drawings, sensor logs and people’s heads. The software that watches over such a structure ages much faster than the structure itself {r('MBD24')}.</p>""",
              f"""<p>Produktionsmaschinen laufen zehn bis fünfzehn Jahre, Brücken fünfzig, Gebäude bis zu hundert. In dieser Zeit werden sie beobachtet, gewartet, eingestellt und erweitert — und das Wissen dafür liegt verstreut in Zeichnungen, Sensorprotokollen und Köpfen. Die Software, die ein solches Bauwerk überwacht, altert viel schneller als das Bauwerk selbst {r('MBD24')}.</p>"""))
        + fig_lifespans(lang)
        + L(T(f"""<p>A digital twin brings that knowledge together and puts it to work: <i>monitoring</i> what happens, <i>predicting</i> what will happen, <i>simulating</i> what would happen, <i>assisting</i> the people who operate the system and, in the end, <i>controlling</i> it. The precondition is simple and often overlooked: the system needs elements in the physical world that can be observed, measured or controlled {r('topic')}.</p>""",
              f"""<p>Ein digitaler Zwilling bündelt dieses Wissen und macht es nutzbar: <i>überwachen</i>, was passiert, <i>vorhersagen</i>, was passieren wird, <i>simulieren</i>, was passieren würde, die Menschen, die das System bedienen, <i>unterstützen</i> und es am Ende <i>steuern</i>. Die Voraussetzung ist einfach und wird oft übersehen: Das System braucht Elemente in der physischen Welt, die sich beobachten, messen oder ansteuern lassen {r('topic')}.</p>"""))))
    S.append(("ladder", 3, T("Model, shadow, twin: the data-flow view", "Modell, Schatten, Zwilling: die Datenfluss-Sicht"),
        L(T(f"""<p>The most popular way to tell the three words apart comes from Kritzinger and colleagues {r('Krit')}. It asks a single question: how automatically does data flow between the real system and its digital counterpart? A <i>digital model</i> has no automated data flow — the CAD model of your car. A <i>digital shadow</i> receives data automatically — the charge level in your app. A <i>digital twin</i> also sends data back automatically — say, a new charging limit, computed from the battery data and sent to the car without anyone typing it in.</p>""",
              f"""<p>Die bekannteste Art, die drei Wörter zu unterscheiden, stammt von Kritzinger und Kollegen {r('Krit')}. Sie stellt eine einzige Frage: Wie automatisch fließen Daten zwischen dem realen System und seinem digitalen Gegenstück? Ein <i>digitales Modell</i> hat keinen automatisierten Datenfluss — das CAD-Modell Ihres Autos. Ein <i>digitaler Schatten</i> bekommt automatisch Daten — der Ladestand in Ihrer App. Ein <i>digitaler Zwilling</i> schickt auch automatisch Daten zurück — etwa ein neues Ladelimit, aus den Batteriedaten berechnet und ans Auto geschickt, ohne dass jemand es eintippt.</p>"""))
        + demo_ladder(lang)
        + L(T(f"""<p>So the app is a shadow. The ladder is a good first step, but it has two limits. It says nothing about what a twin consists of {r('PZC25')}. And it disagrees with the definition used here about one case: if a person carries out what the twin proposes, Kritzinger calls it a shadow. The RWTH definition still calls it a twin, because control through people counts.</p>""",
              f"""<p>Die App ist also ein Schatten. Die Leiter ist ein guter erster Schritt, hat aber zwei Grenzen. Sie sagt nichts darüber, woraus ein Zwilling besteht {r('PZC25')}. Und in einem Fall widerspricht sie der Definition, die hier gilt: Setzt ein Mensch um, was der Zwilling vorschlägt, nennt Kritzinger das einen Schatten. Die RWTH-Definition nennt es weiter einen Zwilling, weil Steuerung über Menschen mitzählt.</p>"""))))
    S.append(("definition", 3, T("The definition: what a twin consists of", "Die Definition: woraus ein Zwilling besteht"),
        L(T("""<p>The RWTH definition does not ask about data flow first, but about the parts. This is its current version, 2.2:</p>""",
              """<p>Die RWTH-Definition fragt nicht zuerst nach dem Datenfluss, sondern nach den Bestandteilen. Dies ist ihre aktuelle Version 2.2:</p>"""))
        + def_box(L(T("Digital twin · RWTH SE, v2.2 (2024)", "Digitaler Zwilling · RWTH SE, v2.2 (2024)")), DT_DEF, f"Rumpe, Michael, Wortmann {r('essay')}", lang, DT_DEF_DE)
        + L(T("""<p>Read it clause by clause. A twin <i>is a software</i> — not a 3D picture, not a single model. It contains <i>models</i>, because data alone means little: a structure model tells where each sensor sits, and so what its readings are about. It contains <i>digital shadows</i> — purpose-bound collections of data (below). Both are <i>purposefully updated on a regular basis</i>: on every event or on a fixed rhythm, with a delay that depends on the purpose. Its <i>services</i> use them — monitoring, prediction, assistance, control. And it <i>interacts</i> with the original system in both directions: it informs, and it commands — from configurations up to hard real-time commands.</p>""",
              """<p>Lesen Sie sie Teil für Teil. Ein Zwilling <i>ist eine Software</i> — kein 3D-Bild, kein einzelnes Modell. Er enthält <i>Modelle</i>, weil Daten allein wenig bedeuten: Ein Strukturmodell sagt, wo jeder Sensor sitzt, und damit, worüber seine Messwerte etwas aussagen. Er enthält <i>digitale Schatten</i> — zweckgebundene Datensammlungen (unten). Beide werden <i>zweckgerichtet und regelmäßig aktualisiert</i>: bei jedem Ereignis oder in einem festen Takt, mit einer Verzögerung, die vom Zweck abhängt. Seine <i>Services</i> nutzen sie — Überwachung, Vorhersage, Assistenz, Steuerung. Und er <i>interagiert</i> in beide Richtungen mit dem Originalsystem: Er informiert, und er gibt Befehle — von Konfigurationen bis zu harten Echtzeitbefehlen.</p>"""))
        + demo_anatomy(lang)
        + L(T("""<p>How do the ladder and the definition fit together? They use the same three words differently:</p>""",
              """<p>Wie passen Leiter und Definition zusammen? Sie verwenden dieselben drei Wörter verschieden:</p>"""))
        + L(T("""<div class="dt-two"><span class="k mono">THE LADDER</span><p>model → shadow → twin are <i>stages</i>, ordered by how automatically data flows.</p>
<span class="k mono">THE RWTH DEFINITION</span><p>models and shadows are <i>parts</i> of a twin.</p></div>""",
              """<div class="dt-two"><span class="k mono">DIE LEITER</span><p>Modell → Schatten → Zwilling sind <i>Stufen</i>, geordnet danach, wie automatisch Daten fließen.</p>
<span class="k mono">DIE RWTH-DEFINITION</span><p>Modelle und Schatten sind <i>Teile</i> eines Zwillings.</p></div>"""))
        + L(T(f"""<p>A shadow can exist on its own, like the app. A twin always contains shadows. And a twin contains models but is not itself a model {r('KMR20')} — the way an application contains a <a href="research-mde.html#classdiagram">class diagram</a> without being one. Its models come from engineering models or are abstracted from the data, which is where chapter 03 picks up.</p>""",
              f"""<p>Ein Schatten kann allein existieren, wie die App. Ein Zwilling enthält immer Schatten. Und ein Zwilling enthält Modelle, ist aber selbst keines {r('KMR20')} — so wie eine Anwendung ein <a href="research-mde.html#classdiagram">Klassendiagramm</a> enthält, ohne eines zu sein. Seine Modelle stammen aus Engineering-Modellen oder werden aus den Daten abstrahiert; dort setzt Kapitel 03 an.</p>"""))
        + curious(lang, T(f"""<p>The definition has a history. The first version (2020) came out of a survey among the Internet of Production’s 25 departments and 200 researchers {r('DMR20')}: “A digital twin of a system consists of a set of models of the system, a set of digital shadows and their aggregation and abstraction collected from a system, and a set of services that allow using the data and models purposefully with respect to the original system.” A shorter form of 2022 is the one my own papers use. Version 2.0 added the regular updates and the way back; 2.1 followed discussions in the model-driven engineering community at a Dagstuhl seminar; 2.2 (2024) adds “is a software”. For people, the RWTH group proposes the same definition under another name — a <i>digital companion</i>, because “twin” means something else in medicine {r('essay')}.</p>""",
                          f"""<p>Die Definition hat eine Geschichte. Die erste Fassung (2020) entstand aus einer Umfrage unter den 25 Instituten und 200 Forschenden des Internet of Production {r('DMR20')}: „A digital twin of a system consists of a set of models of the system, a set of digital shadows and their aggregation and abstraction collected from a system, and a set of services that allow using the data and models purposefully with respect to the original system.“ Eine kürzere Form von 2022 verwenden meine eigenen Arbeiten. Version 2.0 ergänzte die regelmäßige Aktualisierung und den Rückweg; 2.1 folgte Diskussionen in der Community der modellgetriebenen Entwicklung auf einem Dagstuhl-Seminar; 2.2 (2024) ergänzt „ist eine Software“. Für Menschen schlägt die RWTH-Gruppe dieselbe Definition unter anderem Namen vor — einen <i>digitalen Begleiter</i>, weil „Zwilling“ in der Medizin anders besetzt ist {r('essay')}.</p>"""),
                  T("Where the definition comes from", "Woher die Definition kommt")), T("The definition", "Die Definition")))
    S.append(("shadow", 3, T("Digital shadows: data under a purpose", "Digitale Schatten: Daten unter einem Zweck"),
        L(T(f"""<p>Why define shadows at all? Because a complete digital copy of a car — let alone a factory — is out of reach, and not needed. The Internet of Production started from the hypothesis that a well-designed collection of digital shadows is more promising than a full-scale digital twin {r('ERCIM')} — much like a navigation app, which combines abstracted live data from many phones with a map.</p>""",
              f"""<p>Warum überhaupt Schatten definieren? Weil eine vollständige digitale Kopie eines Autos — von einer Fabrik ganz zu schweigen — außer Reichweite ist und nicht gebraucht wird. Das Internet of Production ging von der These aus, dass eine gut entworfene Sammlung digitaler Schatten vielversprechender ist als ein vollständiger Zwilling {r('ERCIM')} — so wie eine Navigations-App abstrahierte Live-Daten vieler Handys mit einer Karte verbindet.</p>"""))
        + def_box(L(T("Digital shadow · RWTH SE", "Digitaler Schatten · RWTH SE")), ("A digital shadow includes", ["a set of contextual data traces and/or", "their aggregation and abstraction collected concerning a system for a specific purpose with respect to the original system."], "", []),
                  f"SE@RWTH {r('topic')}", lang,
                  ("Ein digitaler Schatten umfasst", ["eine Menge kontextbezogener Datenspuren und/oder", "deren Aggregation und Abstraktion, gesammelt über ein System für einen bestimmten Zweck in Bezug auf das Originalsystem."], "", []))
        + L(T(f"""<p>The key word is <i>purpose</i>: each shadow serves exactly one. It is about an <i>asset</i> (your car), collects <i>data traces</i> from <i>sources</i> — sensors, but also people typing in values — and uses a <i>model</i> to make sense of them. Then it answers a question. It never acts: a shadow follows the original system under one particular view; a twin follows it too, but may also change its behaviour {cite('FHM+23')}.</p>""",
              f"""<p>Das Schlüsselwort ist <i>Zweck</i>: Jeder Schatten dient genau einem. Er betrifft ein <i>Asset</i> (Ihr Auto), sammelt <i>Datenspuren</i> aus <i>Quellen</i> — Sensoren, aber auch Menschen, die Werte eintippen — und nutzt ein <i>Modell</i>, um sie zu deuten. Dann beantwortet er eine Frage. Er handelt nie: Ein Schatten folgt dem Originalsystem unter einer bestimmten Sicht; ein Zwilling folgt ihm auch, kann aber sein Verhalten ändern {cite('FHM+23')}.</p>"""))
        + demo_shadows(lang), T("Digital shadows", "Digitale Schatten")))
    S.append(("kinds", 3, T("One type, many instances", "Ein Typ, viele Exemplare"),
        L(T(f"""<p>A twin can exist before its original system is built. While a car model is being designed, its <i>development twin</i> is a coherent set of development artefacts. It has the character of a <i>type</i>, because it may have many instances, and it has no data from a real car, except perhaps from simulations {r('essay')}. Once cars are built, each one gets its own twin — as manufactured, with its tolerances, and as driven, with its wear. If you write software: the development twin is the class, the twin of your car is an object.</p>""",
              f"""<p>Ein Zwilling kann existieren, bevor sein Originalsystem gebaut ist. Solange ein Automodell entworfen wird, ist sein <i>Entwicklungszwilling</i> eine zusammenhängende Menge von Entwicklungsartefakten. Er hat den Charakter eines <i>Typs</i>, weil er viele Exemplare haben kann, und er hat keine Daten eines echten Autos, außer vielleicht aus Simulationen {r('essay')}. Sobald Autos gebaut sind, bekommt jedes seinen eigenen Zwilling — wie gefertigt, mit seinen Toleranzen, und wie gefahren, mit seinem Verschleiß. Wer Software schreibt: Der Entwicklungszwilling ist die Klasse, der Zwilling Ihres Autos ein Objekt.</p>"""))
        + fig_lifecycle(lang)
        + L(T(f"""<p>Does each purpose get its own twin? The RWTH group answers with a riddle: “Logically, there is only one digital twin. If there were several twins, they would not be twins but triplets or more” {r('essay')}. In software terms: one logical system, possibly deployed as several services — in the car, at the edge, in the cloud.</p>""",
              f"""<p>Bekommt jeder Zweck einen eigenen Zwilling? Die RWTH-Gruppe antwortet mit einem Rätsel: Logisch gibt es nur einen digitalen Zwilling; gäbe es mehrere, wären es keine Zwillinge, sondern Drillinge oder mehr {r('essay')}. In Software-Begriffen: ein logisches System, das durchaus als mehrere Services verteilt laufen kann — im Auto, am Edge, in der Cloud.</p>"""))
        + curious(lang, T(f"""<p>A mapping study of 356 papers collected 112 different definitions {r('list')}. Their weak spots fall into four kinds: <i>ambiguous</i> (they defer to another undefined term such as “virtual representation”), <i>narrow</i> (one domain or technology), <i>underspecified</i> (only the data flow, as in the ladder) and <i>utopian</i> (a complete copy of everything). Where they part ways, this article takes one side:</p>
<div class="tbl-wrap"><table class="tbl dt-tbl"><tr><th>Question</th><th>The stance taken here</th></tr>
<tr><td>Does data flow back?</td><td>Yes — directly or through people. Some definitions only mirror the system.</td></tr>
<tr><td>A complete copy?</td><td>No — a twin is always an abstraction for purposes. Early definitions aimed at describing a product completely.</td></tr>
<tr><td>Passive or active?</td><td>Active: a twin is a running software system, not a data structure synchronised from outside.</td></tr>
<tr><td>Before the product exists?</td><td>Yes: the development twin. In practice, though, 266 of the 356 papers address the operation phase, and only 29 develop the twin together with the system {r('DJR22')}.</td></tr></table></div>""",
                          f"""<p>Eine Mapping-Studie über 356 Arbeiten sammelte 112 verschiedene Definitionen {r('list')}. Ihre Schwachstellen fallen in vier Arten: <i>mehrdeutig</i> (sie verweisen auf einen anderen undefinierten Begriff wie „virtuelle Repräsentation“), <i>eng</i> (eine Domäne oder Technik), <i>unterspezifiziert</i> (nur der Datenfluss, wie in der Leiter) und <i>utopisch</i> (eine vollständige Kopie von allem). Wo sie sich trennen, bezieht dieser Artikel Stellung:</p>
<div class="tbl-wrap"><table class="tbl dt-tbl"><tr><th>Frage</th><th>Die Haltung hier</th></tr>
<tr><td>Fließen Daten zurück?</td><td>Ja — direkt oder über Menschen. Manche Definitionen spiegeln das System nur.</td></tr>
<tr><td>Eine vollständige Kopie?</td><td>Nein — ein Zwilling ist immer eine Abstraktion für Zwecke. Frühe Definitionen wollten ein Produkt vollständig beschreiben.</td></tr>
<tr><td>Passiv oder aktiv?</td><td>Aktiv: Ein Zwilling ist ein laufendes Softwaresystem, keine Datenstruktur, die von außen synchronisiert wird.</td></tr>
<tr><td>Vor dem Produkt?</td><td>Ja: der Entwicklungszwilling. In der Praxis behandeln allerdings 266 der 356 Arbeiten die Betriebsphase, und nur 29 entwickeln den Zwilling zusammen mit dem System {r('DJR22')}.</td></tr></table></div>"""),
                  T("Why there are 112 definitions", "Warum es 112 Definitionen gibt"))))

    # ---------------- 02 How a twin works (case study: an injection-moulding machine) ----------------
    S.append(("inside", 2, T("How a twin works", "Wie ein Zwilling arbeitet"), L(T(
        f"<p>The case study of this chapter is the injection-moulding machine that runs through the RWTH group’s twin papers {r('BDH20')}: what does its twin keep, how does it decide, and where do people come in?</p>",
        f"<p>Die Fallstudie dieses Kapitels ist die Spritzgießmaschine, die sich durch die Zwillings-Arbeiten der RWTH-Gruppe zieht {r('BDH20')}: Was hält ihr Zwilling fest, wie entscheidet er, und wo kommen Menschen ins Spiel?</p>"))))
    S.append(("machine", 3, T("Meet the machine", "Die Maschine"),
        L(T(f"""<p>An injection-moulding machine makes plastic parts — here, door handles. Plastic granules fall from the <i>hopper</i> into a heated <i>barrel</i>. A screw turns inside it: it melts the granules with the heat of the heater bands and its own friction, and pushes a measured amount of melt to the front. Then the screw moves forward like a piston and <i>injects</i> the melt into the closed <i>mould</i>. The part cools, the <i>clamping unit</i> opens the mould, the part is ejected — and the cycle starts again. The control cabinet and the user interface set temperatures, pressures and times for every phase.</p>
<p>So the twin’s data are temperatures of the barrel zones, pressures and the verdict OK / not OK for each part; the <i>rejection rate</i> is the share of faulty parts. Too hot, and the material degrades; too cold or too little pressure, and the mould is not filled. Finding the right settings by trial and error takes time, consumes energy and produces waste {cite('DHM+22')}.</p>""",
              f"""<p>Eine Spritzgießmaschine stellt Kunststoffteile her — hier Türgriffe. Kunststoffgranulat fällt aus dem <i>Trichter</i> in einen beheizten <i>Zylinder</i>. Darin dreht sich eine Schnecke: Sie schmilzt das Granulat mit der Wärme der Heizbänder und ihrer eigenen Reibung und fördert eine abgemessene Menge Schmelze nach vorn. Dann fährt die Schnecke wie ein Kolben vor und <i>spritzt</i> die Schmelze in die geschlossene <i>Form</i>. Das Teil kühlt ab, die <i>Schließeinheit</i> öffnet die Form, das Teil wird ausgeworfen — und der Zyklus beginnt von vorn. Schaltschrank und Bedienoberfläche legen Temperaturen, Drücke und Zeiten für jede Phase fest.</p>
<p>Die Daten des Zwillings sind deshalb Temperaturen der Zylinderzonen, Drücke und das Urteil OK / nicht OK für jedes Teil; die <i>Ausschussquote</i> ist der Anteil fehlerhafter Teile. Zu heiß, und das Material wird geschädigt; zu kalt oder zu wenig Druck, und die Form wird nicht gefüllt. Die richtigen Einstellungen durch Versuch und Irrtum zu finden, kostet Zeit, Energie und Material {cite('DHM+22')}.</p>"""))))
    S.append(("loop", 3, T("From data to command: the twin’s loop", "Von Daten zum Befehl: die Schleife des Zwillings"),
        L(T(f"""<p>A thermostat is the smallest loop: measure, compare with the setpoint, switch the heater. A twin’s loop is the same, but each step is a replaceable model. In the injection-moulding twin, four components run in a loop: the <i>data processor</i> collects data and prepares it into shadows, the <i>evaluator</i> notices a problem, the <i>reasoner</i> chooses a fix, the <i>executor</i> sends the command — over standard protocols such as MQTT, OPC UA or REST. The intelligence consists of three kinds of small models: an <i>event</i> says when to act, a <i>goal</i> what should become true, a <i>case</i> how to get there. A new machine needs new cases, not new code {cite('DHM+22')}.</p>""",
              f"""<p>Ein Thermostat ist die kleinste Schleife: messen, mit dem Sollwert vergleichen, die Heizung schalten. Die Schleife eines Zwillings ist dieselbe, nur ist jeder Schritt ein austauschbares Modell. Im Zwilling der Spritzgießmaschine laufen vier Komponenten in einer Schleife: Der <i>Datenprozessor</i> sammelt Daten und bereitet sie zu Schatten auf, der <i>Evaluator</i> bemerkt ein Problem, der <i>Reasoner</i> wählt eine Lösung, der <i>Executor</i> sendet den Befehl — über Standardprotokolle wie MQTT, OPC UA oder REST. Die Intelligenz besteht aus drei Arten kleiner Modelle: Ein <i>Ereignis</i> sagt, wann gehandelt wird, ein <i>Ziel</i>, was gelten soll, ein <i>Fall</i>, wie man hinkommt. Eine neue Maschine braucht neue Fälle, keinen neuen Code {cite('DHM+22')}.</p>"""))
        + demo_loop(lang)
        + L(T("""<p>If no case matches, the reasoner looks for a similar one and adapts it into a new case. The shadow in step 2 is a view like the ones on the car in chapter 01: the last two readings of one sensor, for one purpose.</p>""",
              """<p>Passt kein Fall, sucht der Reasoner einen ähnlichen und leitet daraus einen neuen ab. Der Schatten in Schritt 2 ist eine Sicht wie die am Auto in Kapitel 01: die letzten beiden Werte eines Sensors, für einen Zweck.</p>"""))
        + curious(lang, {k: v + fig_refarch(k) for k, v in T(f"<p>Since then, the loop has grown into a richer architecture {r('HJM24')}:</p>",
                                                              f"<p>Seitdem ist aus der Schleife eine reichere Architektur gewachsen {r('HJM24')}:</p>").items()},
                  T("From one loop to many services", "Von einer Schleife zu vielen Services")), T("The loop", "Die Schleife")))
    S.append(("cockpit", 3, T("People in the loop: cockpits", "Menschen in der Schleife: Cockpits"),
        L(T(f"""<p>Twins can guide people, not only machines. <i>Informative</i> services show what is going on; <i>assistive</i> services lead a person step by step — in a smart kitchen, from “a fillable utensil that can hold at least 3 liters” to “left of the stove, in the drawer cabinet, in the first drawer from below” {r('Mic25')}.</p>
<p>And a twin can explain itself: instead of “h &gt; 70”, it can say that the vehicle stopped because its battery was overheating {r('MSW24')}. All of this needs a user interface — the twin’s cockpit:</p>""",
              f"""<p>Zwillinge können Menschen anleiten, nicht nur Maschinen. <i>Informierende</i> Services zeigen, was passiert; <i>assistierende</i> Services führen einen Menschen Schritt für Schritt — in einer intelligenten Küche etwa von „ein befüllbares Gefäß, das mindestens 3 Liter fasst“ zu „links neben dem Herd, im Schubladenschrank, in der untersten Schublade“ {r('Mic25')}.</p>
<p>Und ein Zwilling kann sich selbst erklären: Statt „h &gt; 70“ sagt er, dass das Fahrzeug anhielt, weil seine Batterie überhitzte {r('MSW24')}. All das braucht eine Benutzeroberfläche — das Cockpit des Zwillings:</p>"""))
        + def_box(L(T("Digital twin cockpit", "Cockpit eines digitalen Zwillings")), ("A digital twin cockpit is the user interaction part (UI/GUI) of a digital twin. It provides the graphical user interface for visualizations of its data organized in digital shadows and models, and the interaction with services of the digital twin, and thus enabling humans to access, adapt and add information and monitor and partially control the physical system.", [], "", []),
                f"Bano et al. {r('BMR22')}, Def. 2", lang,
                ("Ein Cockpit eines digitalen Zwillings ist der Teil für die Interaktion mit Nutzern (UI/GUI). Es bietet die grafische Oberfläche für Visualisierungen seiner Daten, organisiert in digitalen Schatten und Modellen, und für die Interaktion mit den Services des Zwillings, und ermöglicht so Menschen, Informationen abzurufen, anzupassen und zu ergänzen und das physische System zu überwachen und teilweise zu steuern.", [], "", []))
        + L(T(f"""<p>A first cockpit for the injection-moulding machine showed pressure, temperature and status — and a button for a full machine stop {r('DMR20')}. Who presses the button is a design decision, not a technical one: in published use cases the operator decides, or picks from a reduced set of options. You saw the switch in the loop above — it changes one step, not the architecture.</p>""",
              f"""<p>Ein erstes Cockpit für die Spritzgießmaschine zeigte Druck, Temperatur und Status — und einen Knopf für einen vollständigen Maschinenstopp {r('DMR20')}. Wer den Knopf drückt, ist eine Entwurfsentscheidung, keine technische: In veröffentlichten Anwendungsfällen entscheidet die Bedienerin oder wählt aus einer reduzierten Menge von Optionen. Den Schalter haben Sie oben in der Schleife gesehen — er ändert einen Schritt, nicht die Architektur.</p>"""))
        + curious(lang, T(f"""<p>A <i>process-aware</i> cockpit also knows the steps of a process and who performs each — machine, twin or person. Such cockpits can be synthesised from event logs; the approach was tried on a hospital data set with 25,463 events and 6,455 cases {r('BMR22')}. Note: a cockpit in this sense is not the same as the management cockpit MaCoCo from part 1 — same word, different thing.</p>""",
                          f"""<p>Ein <i>prozessbewusstes</i> Cockpit kennt zusätzlich die Schritte eines Prozesses und wer sie ausführt — Maschine, Zwilling oder Mensch. Solche Cockpits lassen sich aus Ereignisprotokollen erzeugen; erprobt wurde das an einem Krankenhaus-Datensatz mit 25.463 Ereignissen und 6.455 Fällen {r('BMR22')}. Hinweis: Ein Cockpit in diesem Sinn ist nicht dasselbe wie das Management-Cockpit MaCoCo aus Teil 1 — gleiches Wort, andere Sache.</p>"""),
                  T("Process-aware cockpits", "Prozessbewusste Cockpits")), T("Cockpits", "Cockpits")))

    # ---------------- 03 Building twins with models ----------------
    S.append(("engineering", 2, T("Building twins with models", "Zwillinge mit Modellen bauen"), L(T(
        "<p>If a twin is software that must live as long as its system, it needs the same discipline as any long-lived software — and models are the way to get it.</p>",
        "<p>Wenn ein Zwilling Software ist, die so lange leben muss wie ihr System, braucht er dieselbe Disziplin wie jede langlebige Software — und Modelle sind der Weg dorthin.</p>"))))
    S.append(("mde", 3, T("A twin is software, so engineer it", "Ein Zwilling ist Software, also bauen Sie ihn wie Software"),
        L(T(f"""<p>Twins use models in two ways: models <i>inside</i> the twin describe the machine; models <i>of</i> the twin describe the twin’s own software — and those are the ones we generate code from. Today, twins are mostly designed and built ad hoc, piece by piece {cite('FHM+23')}. Yet much of what a twin needs already exists: AutomationML, CAD or STEP files, Modelica or SysML models.</p>""",
              f"""<p>Zwillinge nutzen Modelle auf zwei Arten: Modelle <i>im</i> Zwilling beschreiben die Maschine; Modelle <i>des</i> Zwillings beschreiben seine eigene Software — und aus diesen generieren wir Code. Heute werden Zwillinge meist ad hoc und stückweise entworfen und gebaut {cite('FHM+23')}. Dabei existiert vieles, was ein Zwilling braucht, schon: AutomationML-, CAD- oder STEP-Dateien, Modelica- oder SysML-Modelle.</p>"""))
        + fig_mde4dt(lang)
        + L(T(f"""<p>Generators then do for twins what <a href="research-mde.html#generator">part 1</a> showed for information systems: they produce the cockpit, the data structures, and even the connection between the machine and its twin — generated from a few lines that say which sensor port feeds which attribute {r('KMR20')}. Hand-written parts survive regeneration, as with the <a href="research-mde.html#handwritten">TOP mechanism</a>.</p>
<p>Language models can draft such models, too: in my dissertation, GPT-4 produced a valid class diagram for a “Digital Twin of a Hydraulic Press” in 19 of 20 runs {cite('Net24')}. More in <a href="research-ai4se.html#models">part 2</a>.</p>""",
              f"""<p>Generatoren leisten dann für Zwillinge, was <a href="research-mde.html#generator">Teil 1</a> für Informationssysteme gezeigt hat: Sie erzeugen das Cockpit, die Datenstrukturen und sogar die Verbindung zwischen Maschine und Zwilling — generiert aus wenigen Zeilen, die sagen, welcher Sensor-Port welches Attribut speist {r('KMR20')}. Handgeschriebene Teile überstehen die Neugenerierung, wie beim <a href="research-mde.html#handwritten">TOP-Mechanismus</a>.</p>
<p>Auch Sprachmodelle können solche Modelle entwerfen: In meiner Dissertation erzeugte GPT-4 für einen „Digital Twin of a Hydraulic Press“ in 19 von 20 Läufen ein gültiges Klassendiagramm {cite('Net24')}. Mehr in <a href="research-ai4se.html#models">Teil 2</a>.</p>"""))))
    S.append(("lowcode", 3, T("A platform that builds twins", "Eine Plattform, die Zwillinge baut"),
        L(T(f"""<p>WordPress builds websites; a site owner then builds pages without writing code. The same split works for twins. Who configures twins in practice? Mostly domain experts without a software-engineering education — and when we started, there were no low-code platforms for digital twins {cite('DHM+22')}. So we generated a <a href="research-mde.html#lowcode">low-code platform</a> for twins: MontiGem builds the workshop, and the twin designer uses the workshop to build twins. Three roles share the work:</p>""",
              f"""<p>WordPress baut Websites; wer eine Website betreibt, baut dann Seiten, ohne Code zu schreiben. Dieselbe Teilung funktioniert für Zwillinge. Wer konfiguriert Zwillinge in der Praxis? Meist Domänenexperten ohne Softwareausbildung — und als wir anfingen, gab es keine Low-Code-Plattformen für digitale Zwillinge {cite('DHM+22')}. Also haben wir eine <a href="research-mde.html#lowcode">Low-Code-Plattform</a> für Zwillinge generiert: MontiGem baut die Werkstatt, und die Zwillings-Designerin baut in der Werkstatt Zwillinge. Drei Rollen teilen sich die Arbeit:</p>"""))
        + demo_roles(lang)
        + L(T("""<p>When we compared commercial platforms such as Eclipse Ditto, AWS IoT Greengrass, Microsoft’s Digital Twins Definition Language or Siemens MindSphere in 2022, the difference was the behaviour: there, it could not be modelled in low code, so those platforms suited software engineers only. Our approach is one possible implementation, and one question stays open: one big twin, or many separate ones?</p>""",
              """<p>Als wir 2022 kommerzielle Plattformen wie Eclipse Ditto, AWS IoT Greengrass, Microsofts Digital Twins Definition Language oder Siemens MindSphere verglichen, lag der Unterschied im Verhalten: Dort ließ es sich nicht per Low-Code modellieren, die Plattformen eigneten sich also nur für Softwareentwickler. Unser Ansatz ist eine mögliche Umsetzung, und eine Frage bleibt offen: ein großer Zwilling oder viele getrennte?</p>"""))))
    S.append(("wind", 3, T("Case study: a development twin for wind turbines", "Fallstudie: ein Entwicklungszwilling für Windkraftanlagen"),
        L(T(f"""<p>Wind turbines are adapted to every site, and their engineering parameters move between many tools. In the ADD project they were exchanged as e-mail attachments or links to temporary cloud storage — changes did not propagate fast enough, and the tools could not read each other’s formats {cite('MNN+22')}. Our answer was a single source of truth, generated from models: the turbine’s functional model became a class diagram, and MontiGem with <a href="research-mde.html#cd2gui">CD2GUI</a> generated the cockpit from it.</p>""",
              f"""<p>Windkraftanlagen werden an jeden Standort angepasst, und ihre Engineering-Parameter wandern zwischen vielen Werkzeugen. Im Projekt ADD wurden sie als E-Mail-Anhang oder als Link auf einen temporären Cloud-Speicher ausgetauscht — Änderungen kamen zu langsam an, und die Werkzeuge konnten die Formate der anderen nicht lesen {cite('MNN+22')}. Unsere Antwort war eine einzige Quelle der Wahrheit, generiert aus Modellen: Das Funktionsmodell der Anlage wurde zum Klassendiagramm, und MontiGem mit <a href="research-mde.html#cd2gui">CD2GUI</a> generierte daraus das Cockpit.</p>"""))
        + fig_wind(lang)
        + L(T("""<p>Is this a digital twin? It is a <i>development twin</i> — the twin of the turbine type, as designed, like the car model in chapter 01. Shadows from a real turbine, services and the way back were outside the project’s scope. Details are on the <a href="projects-add.html">ADD project page</a>.</p>""",
              """<p>Ist das ein digitaler Zwilling? Es ist ein <i>Entwicklungszwilling</i> — der Zwilling des Anlagentyps, wie entworfen, so wie das Automodell in Kapitel 01. Schatten einer echten Anlage, Services und der Rückweg lagen außerhalb des Projekts. Details stehen auf der <a href="projects-add.html">ADD-Projektseite</a>.</p>""")), T("Case: wind turbines", "Fall: Windkraftanlagen")))
    S.append(("future", 3, T("Twins over decades", "Zwillinge über Jahrzehnte"),
        L(T(f"""<ul class="pts"><li><b>Composition.</b> A car is made of a powertrain, the powertrain of a battery, and many cars form a fleet — twins should be composed the same way, which raises questions of integration, intellectual property, rights and roles {r('MPRW22')}.</li>
<li><b>Evolution.</b> A twin that lives for decades needs a way back from operation into the next development cycle {r('MCZ25')} — and its software will be rebuilt several times on the way, which is where models and generators pay off.</li>
<li><b>AI in and around twins.</b> Process mining and AI are services of a twin; and language models can write the models twins are built from (<a href="research-ai4se.html#models">part 2</a>).</li></ul>""",
              f"""<ul class="pts"><li><b>Komposition.</b> Ein Auto besteht aus einem Antriebsstrang, der Antriebsstrang aus einer Batterie, und viele Autos bilden eine Flotte — Zwillinge sollten genauso zusammengesetzt werden, was Fragen der Integration, des geistigen Eigentums, der Rechte und Rollen aufwirft {r('MPRW22')}.</li>
<li><b>Evolution.</b> Ein Zwilling, der Jahrzehnte lebt, braucht einen Rückweg aus dem Betrieb in den nächsten Entwicklungszyklus {r('MCZ25')} — und seine Software wird unterwegs mehrfach neu gebaut; genau dort zahlen sich Modelle und Generatoren aus.</li>
<li><b>KI in und um Zwillinge.</b> Process Mining und KI sind Services eines Zwillings; und Sprachmodelle können die Modelle schreiben, aus denen Zwillinge gebaut werden (<a href="research-ai4se.html#models">Teil 2</a>).</li></ul>"""))
        + fig_sos(lang)))
    S.append(("summary", 1, T("In short", "Kurz gesagt"),
        L(T(f"""<ul class="pts"><li><b>A twin is software</b> made of models and digital shadows plus services, and it interacts with its original system — it is “not only a simulation model, it is not only a dashboard, and it is not just another term for a CPS” {r('Mic25')}.</li>
<li><b>A shadow is passive</b> and serves one purpose, like a view in a database; the twin also acts.</li>
<li><b>Two views of three words:</b> the ladder asks how automatically data flows; the RWTH definition asks what is inside — models and shadows are parts of a twin, not stages before it.</li>
<li><b>Type and instance:</b> the development twin of a car model is the class; the twin of your car is an object.</li>
<li><b>Humans stay in the loop:</b> the cockpit is the twin’s interface, and whether a command runs automatically is a design decision.</li>
<li><b>Engineer twins model-driven:</b> a twin must live as long as its system, so build it from models and generators — cockpits, connections, whole platforms.</li></ul>""",
              f"""<ul class="pts"><li><b>Ein Zwilling ist Software</b> aus Modellen und digitalen Schatten plus Services, und er interagiert mit seinem Originalsystem — er ist nicht nur ein Simulationsmodell, nicht nur ein Dashboard und nicht bloß ein anderes Wort für ein cyber-physisches System {r('Mic25')}.</li>
<li><b>Ein Schatten ist passiv</b> und dient einem Zweck, wie eine Sicht in einer Datenbank; der Zwilling handelt auch.</li>
<li><b>Zwei Sichten auf drei Wörter:</b> Die Leiter fragt, wie automatisch Daten fließen; die RWTH-Definition fragt, was drin ist — Modelle und Schatten sind Teile eines Zwillings, keine Stufen davor.</li>
<li><b>Typ und Exemplar:</b> Der Entwicklungszwilling eines Automodells ist die Klasse; der Zwilling Ihres Autos ist ein Objekt.</li>
<li><b>Menschen bleiben in der Schleife:</b> Das Cockpit ist die Schnittstelle des Zwillings, und ob ein Befehl automatisch läuft, ist eine Entwurfsentscheidung.</li>
<li><b>Zwillinge modellgetrieben bauen:</b> Ein Zwilling muss so lange leben wie sein System, also bauen Sie ihn aus Modellen und Generatoren — Cockpits, Verbindungen, ganze Plattformen.</li></ul>"""))
        + L(T("""<div class="fit"><div><span class="k mono">A TWIN IS WORTH IT WHEN</span><ul class="pts"><li>there are elements you can observe, measure or control</li><li>the system lives long enough to repay the effort</li><li>someone will act on what it says — automatically or through people</li></ul></div>
<div><span class="k mono">A SHADOW MAY BE ENOUGH WHEN</span><ul class="pts"><li>you only need to watch or analyse</li><li>users do not want automatic control</li><li>there is no way to act back on the system</li></ul></div></div>""",
              """<div class="fit"><div><span class="k mono">EIN ZWILLING LOHNT SICH, WENN</span><ul class="pts"><li>es Elemente gibt, die man beobachten, messen oder steuern kann</li><li>das System lange genug lebt, um den Aufwand zu tragen</li><li>jemand auf das Gesagte reagiert — automatisch oder über Menschen</li></ul></div>
<div><span class="k mono">EIN SCHATTEN REICHT VIELLEICHT, WENN</span><ul class="pts"><li>Sie nur beobachten oder auswerten wollen</li><li>Nutzer keine automatische Steuerung wollen</li><li>es keinen Weg gibt, auf das System zurückzuwirken</li></ul></div></div>"""))
        + f'<div class="tryit"><span class="k mono">{L(T("TRY IT YOURSELF", "SELBST AUSPROBIEREN"))}</span>'
        + tries(lang, [gpt("sysml", T("model a system, e.g. a pump, in SysML v2", "ein System modellieren, z. B. eine Pumpe, in SysML v2")),
                       gpt("cd4a", T("its data as a class diagram", "seine Daten als Klassendiagramm")),
                       gpt("mc", T("MontiCore’s language components and handbook", "Sprachkomponenten und Handbuch von MontiCore"))]) + "</div>"))
    refs = "".join(f'<li id="ref-{k}">{t}</li>' for k, (_, t) in enumerate(REFS, 1))
    # short side-nav labels for the long headings (as in EA)
    NAV = {"why": T("Lifespans", "Lebensdauern"), "ladder": T("Model, shadow, twin", "Modell, Schatten, Zwilling"),
           "mde": T("Engineer it", "Wie Software bauen"), "lowcode": T("A twin platform", "Eine Zwillingsplattform"),
           "future": T("Over decades", "Über Jahrzehnte")}
    S = [it + (NAV[it[0]],) if it[0] in NAV and len(it) == 4 else it for it in S]
    return None, article_common.sections(S, lang), refs


def page(lang):
    """Returns (file, title, description, body, scripts) for build.py; header, literature and series end come from
    article_common (the same for all four parts)."""
    A = "../" if lang == "de" else ""
    _, sections, refs = body(lang, A)
    lead = T("What a digital twin is — and what it is not: models, <em>digital shadows</em> and services, how a twin acts, and how to build twins with models.",
             "Was ein digitaler Zwilling ist — und was nicht: Modelle, <em>digitale Schatten</em> und Services, wie ein Zwilling handelt und wie man Zwillinge mit Modellen baut.")
    desc = T("Digital twins: the definition of RWTH’s Software Engineering group and the Internet of Production, digital shadows, how a twin acts, and how twins are built with models — an article by Lukas Netz.",
             "Digitale Zwillinge: die Definition der Software-Engineering-Gruppe der RWTH und des Internet of Production, digitale Schatten, wie ein Zwilling handelt und wie man Zwillinge mit Modellen baut — ein Artikel von Lukas Netz.")
    return article_common.page(lang, FILE, sections, refs, OWN, article_art.hero_dt(lang), lead, desc, article_common.scripts(lang, "dt", css=True))
